ing(.horizontal, 30)                    .padding(.top, 10)                                        // Navigation Link to Signup                    NavigationLink(destination: SignupView()) {                        Text("New Here? Sign up")                            .foregroundColor(.white)                            .underline()                            .padding(.top, 20)                    }                }            }        }    }        func loginUser() {            errorMessage = ""                        Auth.auth().signIn(withEmail: email, password: password) { result, error in                if let error = error {                    errorMessage = error.localizedDescription                    return                }                                // Grab the user who just tried to log in                guard let user = result?.user else { return }                                // THE BOUNCER CHECK: Did they click the email link?                if user.isEmailVerified {                    print("Successfully logged in and verified!")                    // TODO: Send them to the GrubU Home Feed                } else {                    // If they haven't clicked the link, kick them back out!                    errorMessage = "Please verify your .edu email address before logging in. Check your inbox!"                                        // Force log them out of the device so they can't sneak in                    try? Auth.auth().signOut()                }            }        }}                struct LoginView_Previews: PreviewProvider {        static var previews: some View {            LoginView()        }    }